'use strict';
const assert = require('node:assert/strict');
const { evaluate, ExprError } = require('./src/index');
const col = s => { try { evaluate(s); } catch (e) { assert.ok(e instanceof ExprError, String(e)); return e.column; } return 'no error'; };
const cases = [
  ['-2 ** 2', -4], ['2 ** -1', 0.5], ['2 ** 3 ** 2', 512], ['2 * -3', -6], ['- - 3', 3],
  ['-7 // 2', -4], ['-7 % 3', 2], ['7 % -3', -2], ['6 // -3', 0], ['-6 % 3', 0], ['0 // 5', 0],
  ['1 // 0.1', 9], ['1 % 0.1', 1 % 0.1], ['7.5 // 2', 3], ['-5 % 3.5', 2],
  ['1 < 2 < 3', true], ['3 > 2 > 1', true], ['1 < 3 < 2', false], ['(1 < 2) + 1', 2],
  ['(1 < 2) == 1', true], ['1 == 1 == 1', true], ['max(1 < 2, 0)', true], ['max(1, 1 < 2)', 1],
  ['min(3, 1, 2)', 1], ['abs(-3)', 3], ['abs(1 < 2)', 1], ['.5 + 5. + 1.5e-3', 6.0015],
];
for (const [s, v] of cases) assert.ok(Object.is(evaluate(s), v), `${s} -> ${evaluate(s)} expected ${v}`);
assert.equal(evaluate('a + b', { a: 1, b: 2 }), 3);
let reads = 0;
const vars = { get x() { reads += 1; return 2; } };
assert.equal(evaluate('1 < x < 3', vars), true); assert.equal(reads, 1);
assert.equal(evaluate('2 < 1 < y'), false); // short-circuit skips unknown y
const errs = [['1 + $', 5], ['1 +', 4], ['1 +  ', 6], ['foo(1 +)', 1], ['abs(1, 2)', 1], ['min()', 1],
  ['1 / 0', 3], ['5 // (1 - 1)', 3], ['5 %  0', 3], ['  y', 3], ['min(1,)', 7], ['2 3', 3], ['1 = 2', 3]];
for (const [s, c] of errs) assert.equal(col(s), c, s);
assert.ok(Number.isNaN(evaluate('n % 1', { n: NaN })));
const big = Array.from({ length: 200000 }, (_, i) => String(i % 7)).join(' + ');
const cmp = Array.from({ length: 200000 }, (_, i) => String(i)).join(' < ');
const t = Date.now();
evaluate(big); assert.equal(evaluate(cmp), true); evaluate('-'.repeat(100000) + '1');
console.log('ok', Date.now() - t, 'ms');

